const upper='https://www.ncbi.nlm.nih.gov/books/NBK526056/';
const peripheral='https://openstax.org/books/anatomy-and-physiology-2e/pages/13-4-the-peripheral-nervous-system';
const lower='https://www.ukri.org/wp-content/uploads/2021/12/MRC-011221-AidsToTheExaminationOfThePeripheralNervousSystem.pdf';
const rows=[
 ['Axillary nerve','Deltoid ve teres minor motor işlevi; omuzun dış kısmında sınırlı bir duyu alanı.','Deltoid kuvvetinde ve dış rotasyon katkısında azalma olabilir; omuz duyu alanı etkilenebilir.','Kuadrangüler aralıktan humerusun cerrahi boynu çevresine uzanır.','Omuz abdüksiyonu, deltoid konturu ve ilgili duyu alanını birlikte karşılaştır.',upper],
 ['Musculocutaneous nerve','Kolun ön kas grubuna motor; lateral ön kola duyusal iletim.','Dirsek fleksiyonu ve supinasyon katkısı azalabilir; lateral ön kol duyusu etkilenebilir.','Korakobrakialis ile ilişkili seyreder; lateral antebrachial kutanöz dal olarak devam eder.','Motor kas hedefleri ile terminal kutanöz dalı ayırt et.',upper],
 ['Median nerve','Ön kol fleksörlerinin önemli bölümü ve elde bazı tenar kasların motor kontrolü; elin belirli palmar alanlarında duyu.','Etkiler lezyonun dirsek, ön kol veya el bileği seviyesine göre değişir; proksimal ve karpal tünel etkilenmesi aynı değildir.','Karpal tünelde fleksör tendonlarla komşudur; anterior interosseöz dal farklı bir hedef grubuna gider.','Başparmak işlevi, ön kol kasları ve duyu alanını seviyeye göre karşılaştır.',upper],
 ['Ulnar nerve','Ön kolda fleksör karpi ulnaris ve derin parmak fleksörünün bir bölümü; el iç kaslarının büyük bölümüne motor kontrol.','Parmakların ayrılması–yaklaştırılması ve kavrama etkilenebilir; ulnar el duyu alanı değişebilir.','Dirsekte medial epikondil arkasından; el bileğinde ulnar kanal bölgesinden geçer.','Dirsek ve el bileği seviyelerini, motor ve kutanöz dalları ayırt et.',upper],
 ['Radial nerve','Kol ve ön kol ekstansör sistemine motor; üst ekstremitenin belirli arka bölgelerine duyusal iletim.','Proksimal hasarda el bileği veya parmak ekstansiyonu etkilenebilir; yalnız derin motor dal hasarı duyu dalıyla aynı değildir.','Humerusun radial oluğu, dirsek ve supinator çevresiyle ilişkilidir.','Triseps, bilek–parmak ekstansörleri ve yüzeyel duyu dalını seviyeye göre incele.',upper],
 ['Long thoracic nerve','Serratus anteriora motor kontrol sağlar.','Skapulanın toraks duvarına tutulması ve yukarı rotasyon katkısı bozulabilir.','Göğüs duvarında serratus anterior üzerinde seyreder.','Skapula hareketini ve serratus anterior hedefini incele; kas zayıflığı tek başına lezyon nedenini belirlemez.',upper],
 ['Thoracodorsal nerve','Latissimus dorsi motor kontrolü.','Omuz ekstansiyonu, adduksiyonu ve iç rotasyonuna bu kasın katkısı azalabilir.','Posterior aksiller bölgeden latissimus dorsiye gider.','Tek kasın katkısı ile tüm omuz hareketini birbirinden ayır.',upper],
 ['Dorsal scapular nerve','Romboid kaslara ve levator scapulaeye motor katkı.','Skapula retraksiyonu ve stabilizasyon katkısı azalabilir.','Skapulanın medial kenarı ve onu konumlandıran kaslarla ilişkilidir.','Romboidleri ve levator scapulaeyi trapezius işlevinden ayrı incele.',upper],
 ['Femoral nerve','Ön uyluk motor hedefleri; diz ekstansiyonuna güçlü katkı ve anterior uyluk–medial bacak duyusal yolları.','Diz ekstansiyonu ve bazı kalça fleksiyon katkıları azalabilir; duyu dağılımı dal seviyesine bağlıdır.','İnguinal bağ altından geçer; safen sinir duyusal terminal dalıdır.','Kuadriseps hedefleri ile safen sinirin duyu rolünü ayırt et.',lower],
 ['Obturator nerve','Uyluk medial kas grubunun önemli bölümüne motor kontrol.','Kalça adduksiyon katkısı azalabilir; hedef kas ve dal seviyesi önemlidir.','Obturator kanal aracılığıyla medial uyluğa geçer; anterior ve posterior dalları ayrıdır.','Adduktor magnusun farklı innervasyonlu bölümlerini birlikte incele.',lower],
 ['Sciatic nerve','Tibial ve ortak fibular bileşenleri üzerinden arka uyluk ve distal ekstremite motor–duyusal yolları.','Geniş motor ve duyusal etkiler oluşabilir; tibial ve fibular bileşen etkilenmesi aynı dağılımda olmayabilir.','Pelvisten gluteal bölgeye ve uyluğun arkasına uzanır; tibial ve ortak fibular bileşenleri taşır.','Hamstring hedefleri, bileşen ayrımı ve distal dalları izle.',lower],
 ['Tibial nerve','Bacağın arka kas grupları ve plantar kas hedefleri; ayağın plantar duyusal yolları.','Plantar fleksiyon veya parmak fleksiyonu seviyeye göre etkilenebilir; plantar duyu değişebilir.','Popliteal ve posterior bacak bölgesinden tarsal tünel çevresine uzanır.','Yüzeyel ve derin posterior bölmelerle plantar dalları ayırt et.',lower],
 ['Common fibular nerve|Common peroneal nerve','Derin ve yüzeyel fibular dallara ayrılarak ön–dış bacak motor ve duyusal yollarını taşır.','Dorsifleksiyon ve eversiyon hedefleri etkilenebilir; düşen ayak tek başına bu sinirin lezyonunu kanıtlamaz.','Fibula boynu çevresinde yüzeye yaklaşır; derin ve yüzeyel dalları ayrılır.','Ortak gövdeyi, derin motor hedefleri ve yüzeyel dalı ayrı incele.',lower],
 ['Deep fibular nerve|Deep peroneal nerve','Ön bacak dorsifleksörleri ve parmak ekstansörlerine motor; dar bir dorsal ayak duyu alanı.','Dorsifleksiyon–parmak ekstansiyonu katkısı azalabilir; lezyon seviyesi sonucu değiştirir.','Bacağın ön bölmesindeki damarlarla ilişkilidir.','Tibialis anterior ve parmak ekstansörlerini, yüzeyel fibular hedeflerden ayır.',lower],
 ['Superficial fibular nerve|Superficial peroneal nerve','Lateral bacak fibular kaslarına motor; ayak sırtının önemli bölümüne duyu.','Eversiyon katkısı ve ilgili duyu alanı etkilenebilir; dorsifleksiyon esas olarak derin dal hedefidir.','Bacağın lateral bölmesinden yüzeye geçer.','Lateral kas hedefleri ve dorsal duyu dallarını incele.',lower],
 ['Superior gluteal nerve','Gluteus medius, minimus ve tensor fasciae latae motor kontrolü.','Tek ayak üzerinde pelvis stabilizasyonu ve kalça abdüksiyonu katkısı azalabilir.','Derin gluteal bölgede ilgili kaslara gider.','Pelvis kontrolünü tek bir kas görünümünden bağımsız olarak değerlendirmeyi öğren.',lower],
 ['Inferior gluteal nerve','Gluteus maximusun motor kontrolü.','Kalça ekstansiyonuna katkı azalabilir; özellikle yük altında hareketin mekanik gereksinimi önemlidir.','Gluteus maximusun derin yüzüyle ilişkilidir.','Gluteus maximusu diğer gluteal kasların sinir kontrolünden ayır.',lower],
 ['Phrenic nerve','Diyaframın motor uyarısı; ilişkili bazı seröz yüzeylerden duyusal iletim.','Tek ve çift taraflı diyafram işlev kaybı aynı değildir; solunum rezervi etkilenebilir.','Boyundan toraksa, akciğer kökünün önünden diyaframa ulaşır.','Diyafram hedefi, kalp–akciğer kökü komşulukları ve tarafı birlikte incele.',peripheral]
];
const clean=s=>s.toLowerCase().replace(/\.[lr]\.\d+$|\.\d+$/g,'').trim();const cards=new Map();for(const [names,normal,injury,relations,check,source]of rows)for(const name of names.split('|'))cards.set(clean(name),{normal,injury,relations,check,source,label:'Sinir hedefleri ve lezyon düzeyi',loss:'Tam sinir iletim kaybı, etkilenen motor–duyusal liflerin hedeflerinde işlev kaybına neden olabilir. Belirtiler dal seviyesi, hasar yaygınlığı ve başka nedenlerle birlikte değerlendirilir.'});
export function nerveStudy(r){return r.layer==='nervous'?cards.get(clean(r.name))||null:null;}
export const nerveStudyCount=cards.size;
